triggers.sql:
CREATE OR REPLACE FUNCTION update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sections_updated_at BEFORE UPDATE ON sections
FOR EACH ROW EXECUTE FUNCTION update_timestamp();

-- Répéter pour toutes les tables avec updated_at

CREATE OR REPLACE FUNCTION update_stock_after_mouvement()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.type_mouvement = 'Entrée' THEN
    UPDATE articles_magasin 
    SET quantite_stock = quantite_stock + NEW.quantite
    WHERE id = NEW.article_id;
  ELSIF NEW.type_mouvement = 'Sortie' THEN
    UPDATE articles_magasin 
    SET quantite_stock = quantite_stock - NEW.quantite
    WHERE id = NEW.article_id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_stock AFTER INSERT ON mouvements_stock
FOR EACH ROW EXECUTE FUNCTION update_stock_after_mouvement();

